INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e6f2caf0-7419-5dc5-916d-77f77e507db8', 'Spain Good Governance Code of Listed Companies', 'Good Governance Code of Listed Companies, 2015', 'The objectives pursued in this Code were to ensure the proper functioning of the governing and administrative bodies of Spanish companies in order to maximize competitiveness, build trust and transparency for shareholders and domestic and foreign investors, improve internal control and corporate responsibility systems, and ensure the correct internal distribu- tion of functions, duties and responsibilities under standards of maximum rigour and professionalism.', 'The objectives pursued in this Code were to ensure the proper functioning of the governing and administrative bodies of Spanish companies in order to maximize competitiveness, build trust and transparency for shareholders and domestic and foreign investors, improve internal control and corporate responsibility systems, and ensure the correct internal distribu- tion of functions, duties and responsibilities under standards of maximum rigour and professionalism.', 'The objectives pursued in this Code were to ensure the proper functioning of the governing and administrative bodies of Spanish companies in order to maximize competitiveness, build trust and transparency for shareholders and domestic and foreign investors, improve internal control and corporate responsibility systems, and ensure the correct internal distribu- tion of functions, duties and responsibilities under standards of maximum rigour and professionalism.', 'Spain', 'governance', 'in_force', '2015-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_37', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('71087f8f-538f-5b34-b8a1-4e90705d432a', 'Spain Royal Decree , of September 21, which approves', 'Royal Decree 840/2015, of September 21, which approves control measures for the risks inherent in serious accidents involving dangerous substances', 'Companies storing large amounts of dangerous substances, such as chlorine, acetylene and anhydrous ammonia are required from Oct. 20, 2015, to comply with stricter requirements under Royal Decree 840/2015 transposing the SEVESO III Directive into domestic law. Operators of major-accident hazard facilities must comply with amended obligations on the notification to be made by companies classified as a Seveso III-facility, the major-accident prevention policy (politica de prevencion de accidentes graves) and the safety report (informe de seguridad).', 'Companies storing large amounts of dangerous substances, such as chlorine, acetylene and anhydrous ammonia are required from Oct. 20, 2015, to comply with stricter requirements under Royal Decree 840/2015 transposing the SEVESO III Directive into domestic law. Operators of major-accident hazard facilities must comply with amended obligations on the notification to be made by companies classified as a Seveso III-facility, the major-accident prevention policy (politica de prevencion de accidentes graves) and the safety report (informe de seguridad).', 'Companies storing large amounts of dangerous substances, such as chlorine, acetylene and anhydrous ammonia are required from Oct. 20, 2015, to comply with stricter requirements under Royal Decree 840/2015 transposing the SEVESO III Directive into domestic law. Operators of major-accident hazard facilities must comply with amended obligations on the notification to be made by companies classified as a Seveso III-facility, the major-accident prevention policy (politica de prevencion de accidentes graves) and the safety report (informe de seguridad).', 'Spain', 'climate', 'in_force', '2015-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_60', ARRAY['spain', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('293fe56c-7547-5ee6-9a6a-759d4faf1c9d', 'Spain Royal Decree , of March 14, which creates', 'Royal Decree 163/2014, of March 14, which creates the carbon footprint registry, compensation and carbon dioxide absorption projects', 'This royal decree, through the creation of the carbon footprint register, compensation and CO2 absorption projects, seeks to raise awareness and encourage society as a whole in the fight against climate change in order to achieve a low carbon economy. carbon, responding to the growing commitment that both public and private entities have been showing in recent years in relation to the reduction of GHG emissions. To this end, a series of measures are established to facilitate and promote the calculation of the carbon footprint, its reduction and compensation through CO2 absorption.', 'This royal decree, through the creation of the carbon footprint register, compensation and CO2 absorption projects, seeks to raise awareness and encourage society as a whole in the fight against climate change in order to achieve a low carbon economy. carbon, responding to the growing commitment that both public and private entities have been showing in recent years in relation to the reduction of GHG emissions. To this end, a series of measures are established to facilitate and promote the calculation of the carbon footprint, its reduction and compensation through CO2 absorption.', 'This royal decree, through the creation of the carbon footprint register, compensation and CO2 absorption projects, seeks to raise awareness and encourage society as a whole in the fight against climate change in order to achieve a low carbon economy. carbon, responding to the growing commitment that both public and private entities have been showing in recent years in relation to the reduction of GHG emissions. To this end, a series of measures are established to facilitate and promote the calculation of the carbon footprint, its reduction and compensation through CO2 absorption.', 'Spain', 'climate', 'in_force', '2014-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_1', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e094a9b8-af79-5b58-9a90-3e3dacdd68a6', 'Spain Act , amending the Companies Act (“Ley de', 'Act 31/2004, amending the Companies Act (“Ley de Sociedades de Capital”)', 'The background to this Act is the Cabinet Resolution of 10 May 2013, whereby a committee of experts on corporate governance (“Committee of Experts”) was created for the purposes of ensuring the good governance of Spanish companies. This Committee was tasked with safeguarding the proper functioning of corporate bodies, which comprise the Board of Directors and the General Meeting, to promote the highest levels of competitiveness, generating trust and transparency for domestic and foreign investors and shareholders, improving internal control and corporate responsibility and ensuring an adequate separation of functions, duties and responsibilities, with the utmost professionalism and rigour.', 'The background to this Act is the Cabinet Resolution of 10 May 2013, whereby a committee of experts on corporate governance (“Committee of Experts”) was created for the purposes of ensuring the good governance of Spanish companies. This Committee was tasked with safeguarding the proper functioning of corporate bodies, which comprise the Board of Directors and the General Meeting, to promote the highest levels of competitiveness, generating trust and transparency for domestic and foreign investors and shareholders, improving internal control and corporate responsibility and ensuring an adequate separation of functions, duties and responsibilities, with the utmost professionalism and rigour.', 'The background to this Act is the Cabinet Resolution of 10 May 2013, whereby a committee of experts on corporate governance (“Committee of Experts”) was created for the purposes of ensuring the good governance of Spanish companies. This Committee was tasked with safeguarding the proper functioning of corporate bodies, which comprise the Board of Directors and the General Meeting, to promote the highest levels of competitiveness, generating trust and transparency for domestic and foreign investors and shareholders, improving internal control and corporate responsibility and ensuring an adequate separation of functions, duties and responsibilities, with the utmost professionalism and rigour.', 'Spain', 'governance', 'in_force', '2014-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_18', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c1301232-102a-5769-a735-fa4d955e3472', 'Spain Law , of December 3, which modifies the', 'Law 31/2014, of December 3, which modifies the Capital Companies Law to improve corporate governance', 'In 2014, Spain enacted "Ley 31/2014, de 3 de diciembre, por la que se modifica la Ley de Sociedades de Capital para la mejora del gobierno corporativo" or Law 31/2014, of December 3, which amends the Spanish Capital Companies Law to improve corporate governance. The law introduces a range of measures aimed at enhancing transparency and accountability in the management of Spanish companies, particularly those listed on the stock exchange. The measures include requiring companies to disclose more information about their governance structures and policies, and to establish committees to oversee risk management, audit, and remuneration. The law also introduces rules on shareholder rights, including greater transparency in relation to voting rights and the right to call shareholder meetings. Overall, the aim of the law is to strengthen the corporate governance framework in Spain and improve investor confidence in the country''s business environment.', 'In 2014, Spain enacted "Ley 31/2014, de 3 de diciembre, por la que se modifica la Ley de Sociedades de Capital para la mejora del gobierno corporativo" or Law 31/2014, of December 3, which amends the Spanish Capital Companies Law to improve corporate governance. The law introduces a range of measures aimed at enhancing transparency and accountability in the management of Spanish companies, particularly those listed on the stock exchange. The measures include requiring companies to disclose more information about their governance structures and policies, and to establish committees to oversee risk management, audit, and remuneration. The law also introduces rules on shareholder rights, including greater transparency in relation to voting rights and the right to call shareholder meetings. Overall, the aim of the law is to strengthen the corporate governance framework in Spain and improve investor confidence in the country''s business environment.', 'In 2014, Spain enacted "Ley 31/2014, de 3 de diciembre, por la que se modifica la Ley de Sociedades de Capital para la mejora del gobierno corporativo" or Law 31/2014, of December 3, which amends the Spanish Capital Companies Law to improve corporate governance. The law introduces a range of measures aimed at enhancing transparency and accountability in the management of Spanish companies, particularly those listed on the stock exchange. The measures include requiring companies to disclose more information about their governance structures and policies, and to establish committees to oversee risk management, audit, and remuneration. The law also introduces rules on shareholder rights, including greater transparency in relation to voting rights and the right to call shareholder meetings. Overall, the aim of the law is to strengthen the corporate governance framework in Spain and improve investor confidence in the country''s business environment.', 'Spain', 'governance', 'in_force', '2014-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_36', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0e0f04d8-add6-535b-b50b-897932f8682d', 'Spain Spanish Strategy for Corporate Social Responsibility', 'Spanish Strategy for Corporate Social Responsibility', 'The Strategy  aims to promote social responsibility among the largest possible number of organisations, so that they all include initiatives in this area within their own culture and values. It should also serve as an effective tool for compliance with the principles of Act 20/2013 of 9 December on the Guarantee of Market Unity in this area.', 'The Strategy  aims to promote social responsibility among the largest possible number of organisations, so that they all include initiatives in this area within their own culture and values. It should also serve as an effective tool for compliance with the principles of Act 20/2013 of 9 December on the Guarantee of Market Unity in this area.', 'The Strategy  aims to promote social responsibility among the largest possible number of organisations, so that they all include initiatives in this area within their own culture and values. It should also serve as an effective tool for compliance with the principles of Act 20/2013 of 9 December on the Guarantee of Market Unity in this area.', 'Spain', 'social', 'in_force', '2014-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_5', ARRAY['sdg8', 'other sustainability policy', 'mandatory', 'mandatory_regulations', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ea1c785f-5bfc-5e40-9506-849ea5bbc01a', 'Spain Approved the ministerial order on Corporate Governance rules', 'Approved the ministerial order on Corporate Governance rules', 'The Minister of Economy and Competitiveness, Luis de Guindos, has signed the ministerial order regulating the structure of the Annual Corporate Governance Report, the Annual Remuneration Report and other information instruments required of listed corporations, savings banks and other Entities that issue securities admitted to trading in the official securities markets. The object is to strengthen and expand the information that must contain the Annual Corporate Governance Report of these companies.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e8fa5807-0f74-580b-b99d-1987848955de', 'Spain Unified Code of Good Governance of Listed Companies', 'Unified Code of Good Governance of Listed Companies', 'Article 61 bis of the Securities Market Law, faithful to the principle known internationally as "comply or explain" (), obliges Spanish listed companies to the recommendations of corporate governance or, where appropriate, the explanation of the lack of follow-up of said recommendations”. The present Code formulates the recommendations that listed companies should consider in order to comply with the information obligation imposed by this precept.', 'Article 61 bis of the Securities Market Law, faithful to the principle known internationally as "comply or explain" (), obliges Spanish listed companies to the recommendations of corporate governance or, where appropriate, the explanation of the lack of follow-up of said recommendations”. The present Code formulates the recommendations that listed companies should consider in order to comply with the information obligation imposed by this precept.', 'Article 61 bis of the Securities Market Law, faithful to the principle known internationally as "comply or explain" (), obliges Spanish listed companies to the recommendations of corporate governance or, where appropriate, the explanation of the lack of follow-up of said recommendations”. The present Code formulates the recommendations that listed companies should consider in order to comply with the information obligation imposed by this precept.', 'Spain', 'governance', 'in_force', '2013-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_21', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1a86cbb8-0486-5072-815d-0f05f2ffad67', 'Spain Order ECC/', 'Order ECC/461/2013', 'The regulations on corporate governance have undergone substantial evolution in recent years, both at the community level and at the national level. Its relevance and usefulness in guaranteeing the proper functioning of the markets has led the public powers to increase and perfect the existing obligations on the matter, which has included, among other actions, the approval of the Unified Code of Good Governance of companies listed anonymous.', 'The regulations on corporate governance have undergone substantial evolution in recent years, both at the community level and at the national level. Its relevance and usefulness in guaranteeing the proper functioning of the markets has led the public powers to increase and perfect the existing obligations on the matter, which has included, among other actions, the approval of the Unified Code of Good Governance of companies listed anonymous.', 'The regulations on corporate governance have undergone substantial evolution in recent years, both at the community level and at the national level. Its relevance and usefulness in guaranteeing the proper functioning of the markets has led the public powers to increase and perfect the existing obligations on the matter, which has included, among other actions, the approval of the Unified Code of Good Governance of companies listed anonymous.', 'Spain', 'governance', 'in_force', '2013-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_35', ARRAY['regulations', 'sdg11', 'mandatory', 'sdg16', 'disclosure', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('26708fde-b207-5e3b-8125-a2a1c91c8897', 'Spain Law , of December 9, on environmental assessment', 'Law 21/2013, of December 9, on environmental assessment', 'Law 21/2013 establishes two environmental assessment procedure—one for those projects with lower environmental impact and another for those activities with a greater environmental impact. In addition, there are two procedures for each type of assessment—a regular procedure and a simplified procedure. Generally a regular environmental impact assessment procedure is required for projects listed in Annex I to Law 21/2013, and a simplified environmental impact statement is required for projects listed in Annex II to Law 21/2013. The regular environmental impact procedure ends with an Environmental Impact Statement (Declaracion de Impacto Ambiental) that includes conditions for project development as well as monitoring conditions. The simplified procedure ends with an Environmental Impact Report (Informe de Impacto Ambiental), which also contains performance conditions and monitoring conditions.', 'Law 21/2013 establishes two environmental assessment procedure—one for those projects with lower environmental impact and another for those activities with a greater environmental impact. In addition, there are two procedures for each type of assessment—a regular procedure and a simplified procedure. Generally a regular environmental impact assessment procedure is required for projects listed in Annex I to Law 21/2013, and a simplified environmental impact statement is required for projects listed in Annex II to Law 21/2013. The regular environmental impact procedure ends with an Environmental Impact Statement (Declaracion de Impacto Ambiental) that includes conditions for project development as well as monitoring conditions. The simplified procedure ends with an Environmental Impact Report (Informe de Impacto Ambiental), which also contains performance conditions and monitoring conditions.', 'Law 21/2013 establishes two environmental assessment procedure—one for those projects with lower environmental impact and another for those activities with a greater environmental impact. In addition, there are two procedures for each type of assessment—a regular procedure and a simplified procedure. Generally a regular environmental impact assessment procedure is required for projects listed in Annex I to Law 21/2013, and a simplified environmental impact statement is required for projects listed in Annex II to Law 21/2013. The regular environmental impact procedure ends with an Environmental Impact Statement (Declaracion de Impacto Ambiental) that includes conditions for project development as well as monitoring conditions. The simplified procedure ends with an Environmental Impact Report (Informe de Impacto Ambiental), which also contains performance conditions and monitoring conditions.', 'Spain', 'climate', 'in_force', '2013-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_55', ARRAY['spain', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2802ca09-a6a8-583c-b1ff-1f0a36c275db', 'Spain Guide for the preparation of the management report', 'Guide for the preparation of the management report of listed entities', 'This Guide contains recommendations that listed companies can follow to prepare the management reports that accompany the annual accounts, the content of which, according to the legal mandate, must be a faithful presentation of the evolution of the business and the situation of the entity, together with a description of the main risks and uncertainties it faces.', 'This Guide contains recommendations that listed companies can follow to prepare the management reports that accompany the annual accounts, the content of which, according to the legal mandate, must be a faithful presentation of the evolution of the business and the situation of the entity, together with a description of the main risks and uncertainties it faces.', 'This Guide contains recommendations that listed companies can follow to prepare the management reports that accompany the annual accounts, the content of which, according to the legal mandate, must be a faithful presentation of the evolution of the business and the situation of the entity, together with a description of the main risks and uncertainties it faces.', 'Spain', 'climate', 'in_force', '2012-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_3', ARRAY['spain', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1a569f28-2469-540c-850d-48fdcbaa43d2', 'Spain Sustainable Economy', 'Law No. 2/2011, of March 4, on Sustainable Economy', 'This Strategy articulates an ambitious and demanding program of reforms, which deepens in the direction of some of the strategic options adopted since the previous Legislature, such as the priority granted to the increase in investment in research, development and innovation, or to the promotion of activities related to clean energy and energy saving.', 'This Strategy articulates an ambitious and demanding program of reforms, which deepens in the direction of some of the strategic options adopted since the previous Legislature, such as the priority granted to the increase in investment in research, development and innovation, or to the promotion of activities related to clean energy and energy saving.', 'This Strategy articulates an ambitious and demanding program of reforms, which deepens in the direction of some of the strategic options adopted since the previous Legislature, such as the priority granted to the increase in investment in research, development and innovation, or to the promotion of activities related to clean energy and energy saving.', 'Spain', 'climate', 'in_force', '2011-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_11', ARRAY['sdg14', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'spain', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a0e728c2-7e7e-5e60-bd97-71b2dbd4e083', 'Spain Law , of July 28, on waste', 'Law 22/2011, of July 28, on waste and contaminated soil', 'Law 22/2011 on Waste and Contaminated Land transposed Directive 2008/98/EC on waste (Waste Framework Directive) and established the general waste management policy to be implemented by the environmental authorities to control waste management operations, reporting, storage, shipment, reuse, recycling and recovery of non-hazardous and hazardous waste. General waste policies implemented under Law 22/2011 must be based on the following waste hierarchy: prevention, preparation for reuse, recycling, other forms of recovery including energy recovery and disposal. Under Article 27 of Chapter III of Law 22/2011 on Waste and Contaminated Land, operators of waste treatment, including storage awaiting recovery and recycling operations, must be authorized by the autonomous community environmental authority. Waste treatment authorizations are valid for eight years, subject to renewal. The producer of waste must keep a record of waste treatment operations, which must include information on the quantity, origin, type, collection, treatment, recovery or recycling operation methods performed on-site. These records must be kept on an annual basis and must be available for at least three years. In addition, waste disposal operators must submit an annual report to the environmental authority of the autonomous community. Operators are under a general obligation to provide information to the authorities periodically to enable them to determine whether the land is contaminated. The government is obliged to keep a register of potentially contaminating activities (the list of which is contained in Royal Decree 9/2005).', 'Law 22/2011 on Waste and Contaminated Land transposed Directive 2008/98/EC on waste (Waste Framework Directive) and established the general waste management policy to be implemented by the environmental authorities to control waste management operations, reporting, storage, shipment, reuse, recycling and recovery of non-hazardous and hazardous waste. General waste policies implemented under Law 22/2011 must be based on the following waste hierarchy: prevention, preparation for reuse, recycling, other forms of recovery including energy recovery and disposal. Under Article 27 of Chapter III of Law 22/2011 on Waste and Contaminated Land, operators of waste treatment, including storage awaiting recovery and recycling operations, must be authorized by the autonomous community environmental authority. Waste treatment authorizations are valid for eight years, subject to renewal. The producer of waste must keep a record of waste treatment operations, which must include information on the quantity, origin, type, collection, treatment, recovery or recycling operation methods performed on-site. These records must be kept on an annual basis and must be available for at least three years. In addition, waste disposal operators must submit an annual report to the environmental authority of the autonomous community. Operators are under a general obligation to provide information to the authorities periodically to enable them to determine whether the land is contaminated. The government is obliged to keep a register of potentially contaminating activities (the list of which is contained in Royal Decree 9/2005).', 'Law 22/2011 on Waste and Contaminated Land transposed Directive 2008/98/EC on waste (Waste Framework Directive) and established the general waste management policy to be implemented by the environmental authorities to control waste management operations, reporting, storage, shipment, reuse, recycling and recovery of non-hazardous and hazardous waste. General waste policies implemented under Law 22/2011 must be based on the following waste hierarchy: prevention, preparation for reuse, recycling, other forms of recovery including energy recovery and disposal. Under Article 27 of Chapter III of Law 22/2011 on Waste and Contaminated Land, operators of waste treatment, including storage awaiting recovery and recycling operations, must be authorized by the autonomous community environmental authority. Waste treatment authorizations are valid for eight years, subject to renewal. The producer of waste must keep a record of waste treatment operations, which must include information on the quantity, origin, type, collection, treatment, recovery or recycling operation methods performed on-site. These records must be kept on an annual basis and must be available for at least three years. In addition, waste disposal operators must submit an annual report to the environmental authority of the autonomous community. Operators are under a general obligation to provide information to the authorities periodically to enable them to determine whether the land is contaminated. The government is obliged to keep a register of potentially contaminating activities (the list of which is contained in Royal Decree 9/2005).', 'Spain', 'climate', 'in_force', '2011-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_56', ARRAY['regulations', 'sdg7', 'sdg11', 'mandatory', 'sdg12', 'disclosure', 'spain', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('41985496-724a-53ac-97a0-e68008c0fd6c', 'Spain Law , of December 9, on corporate social', 'Law 15/2010, of December 9, on corporate social responsibility in Extremadura', 'This document outlines the law 15/2010, of December 9, on corporate social responsibility in Extremadura.', 'This document outlines the law 15/2010, of December 9, on corporate social responsibility in Extremadura.', 'This document outlines the law 15/2010, of December 9, on corporate social responsibility in Extremadura.', 'Spain', 'governance', 'in_force', '2010-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_4', ARRAY['spain', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1d957be6-80cc-5b06-900f-99bcf1bcb338', 'Spain Royal Decree , of February 5, which modifies', 'Royal Decree 105/2010, of February 5, which modifies certain aspects of the regulation of the storage of chemical products and approves the complementary technical instruction MIE APQ-9 "storage of organic peroxides"', 'Companies storing explosives, such as ammonium nitrate, above certain thresholds are required to comply with updated requirements, effective Nov. 25, 2015. The main changes are stricter inspection requirements and the obligation to provide certain information to the public, such as information on how the concerned population will be warned and how they should behave in the event of a major accident. In addition, operators of the existing facilities must submit an updated notification; a written policy document for the prevention of major accidents (politica de prevencion de accidentes graves); and a safety report (informe de seguridad) for upper-tier facilities to the Government (Delegacion del Gobierno) in the autonomous community where the facility is located.', 'Companies storing explosives, such as ammonium nitrate, above certain thresholds are required to comply with updated requirements, effective Nov. 25, 2015. The main changes are stricter inspection requirements and the obligation to provide certain information to the public, such as information on how the concerned population will be warned and how they should behave in the event of a major accident. In addition, operators of the existing facilities must submit an updated notification; a written policy document for the prevention of major accidents (politica de prevencion de accidentes graves); and a safety report (informe de seguridad) for upper-tier facilities to the Government (Delegacion del Gobierno) in the autonomous community where the facility is located.', 'Companies storing explosives, such as ammonium nitrate, above certain thresholds are required to comply with updated requirements, effective Nov. 25, 2015. The main changes are stricter inspection requirements and the obligation to provide certain information to the public, such as information on how the concerned population will be warned and how they should behave in the event of a major accident. In addition, operators of the existing facilities must submit an updated notification; a written policy document for the prevention of major accidents (politica de prevencion de accidentes graves); and a safety report (informe de seguridad) for upper-tier facilities to the Government (Delegacion del Gobierno) in the autonomous community where the facility is located.', 'Spain', 'climate', 'in_force', '2010-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_59', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'spain', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9aab8cef-5771-53bb-8f8c-3cbeeb490246', 'Spain Self-evaluation Questionnaire on Good Corporate Governance for Unlisted', 'Self-evaluation Questionnaire on Good Corporate Governance for Unlisted Companies', 'This Self-evaluation questionnaire is structured under two general headings: Company Governance and Governance of the Business Family (an additional heading for Unlisted family businesses). In turn, the heading of Company Governance includes evolution of the Board of Directors /Advisory Board, in 3 phases, with specific questions for each any every one of these, as well as a specific area for the Shareholders’ Meeting. These questions are answered with a plain “Yes”, “No” or “Partially”.', 'This Self-evaluation questionnaire is structured under two general headings: Company Governance and Governance of the Business Family (an additional heading for Unlisted family businesses). In turn, the heading of Company Governance includes evolution of the Board of Directors /Advisory Board, in 3 phases, with specific questions for each any every one of these, as well as a specific area for the Shareholders’ Meeting. These questions are answered with a plain “Yes”, “No” or “Partially”.', 'This Self-evaluation questionnaire is structured under two general headings: Company Governance and Governance of the Business Family (an additional heading for Unlisted family businesses). In turn, the heading of Company Governance includes evolution of the Board of Directors /Advisory Board, in 3 phases, with specific questions for each any every one of these, as well as a specific area for the Shareholders’ Meeting. These questions are answered with a plain “Yes”, “No” or “Partially”.', 'Spain', 'governance', 'in_force', '2008-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_34', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d0c4ae70-82d4-5a8e-9071-428bc04a2455', 'Spain Spanish General Accounting Plan', 'Spanish General Accounting Plan', 'The General Accounting Plan, adapted to the relevant provisions of Law 16/2007, is the work of an extensive ensemble of accounting experts, brought together with the aim of achieving an appropriate balance between companies preparing information, users of that information, expert accounting professionals, university professors in the field and government representatives.', 'The General Accounting Plan, adapted to the relevant provisions of Law 16/2007, is the work of an extensive ensemble of accounting experts, brought together with the aim of achieving an appropriate balance between companies preparing information, users of that information, expert accounting professionals, university professors in the field and government representatives.', 'The General Accounting Plan, adapted to the relevant provisions of Law 16/2007, is the work of an extensive ensemble of accounting experts, brought together with the aim of achieving an appropriate balance between companies preparing information, users of that information, expert accounting professionals, university professors in the field and government representatives.', 'Spain', 'governance', 'in_force', '2007-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_10', ARRAY['spain', 'mandatory', 'other sustainability policy', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3f4541ab-62d4-5968-9975-457f0d8fe1a5', 'Spain Constitutional Act of 22 March for effective equality', 'Constitutional Act 3/2007 of 22 March for effective equality between women and men', 'Article 14 of the Spanish Constitution proclaims the right to equality and non- discrimination on the grounds of sex. Article 9.2, in turn, ratifies public authorities’ obligation to further conditions that will ensure that individuals, and the groups of which they form a part, enjoy real and effective equality.', 'Article 14 of the Spanish Constitution proclaims the right to equality and non- discrimination on the grounds of sex. Article 9.2, in turn, ratifies public authorities’ obligation to further conditions that will ensure that individuals, and the groups of which they form a part, enjoy real and effective equality.', 'Article 14 of the Spanish Constitution proclaims the right to equality and non- discrimination on the grounds of sex. Article 9.2, in turn, ratifies public authorities’ obligation to further conditions that will ensure that individuals, and the groups of which they form a part, enjoy real and effective equality.', 'Spain', 'social', 'in_force', '2007-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_33', ARRAY['other sustainability policy', 'sdg10', 'regulations', 'mandatory', 'sdg5', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('692ba696-0f89-5ef2-9ed7-6e48a76ea65d', 'Spain Law , of November 15, on air quality', 'Law 34/2007, of November 15, on air quality and protection of the atmosphere', 'Spanish Decree 833, among others, was adopted to establish air quality standards for major pollutants and to create a framework for enforcement of Spanish environmental law. This decree has been modified and various resolutions issued to seek compliance with the EU directive. Facilities are required to monitor and measure emissions and report on them according to the frequency and schedule established for the industry concerned. Activities included under the scope of Law 34/2007 are required to implement the best available technology and have the necessary pollution control equipment or devices to prevent and reduce pollution emissions. If there is an interruption or accidental failure of this equipment, the operator must notify the competent authorities immediately. During this period, the applicable emission limit values would not apply, but the undertaking would be required to comply with special temporary operating conditions established in the operating authorization or by the competent authority in each case.', 'Spanish Decree 833, among others, was adopted to establish air quality standards for major pollutants and to create a framework for enforcement of Spanish environmental law. This decree has been modified and various resolutions issued to seek compliance with the EU directive. Facilities are required to monitor and measure emissions and report on them according to the frequency and schedule established for the industry concerned. Activities included under the scope of Law 34/2007 are required to implement the best available technology and have the necessary pollution control equipment or devices to prevent and reduce pollution emissions. If there is an interruption or accidental failure of this equipment, the operator must notify the competent authorities immediately. During this period, the applicable emission limit values would not apply, but the undertaking would be required to comply with special temporary operating conditions established in the operating authorization or by the competent authority in each case.', 'Spanish Decree 833, among others, was adopted to establish air quality standards for major pollutants and to create a framework for enforcement of Spanish environmental law. This decree has been modified and various resolutions issued to seek compliance with the EU directive. Facilities are required to monitor and measure emissions and report on them according to the frequency and schedule established for the industry concerned. Activities included under the scope of Law 34/2007 are required to implement the best available technology and have the necessary pollution control equipment or devices to prevent and reduce pollution emissions. If there is an interruption or accidental failure of this equipment, the operator must notify the competent authorities immediately. During this period, the applicable emission limit values would not apply, but the undertaking would be required to comply with special temporary operating conditions established in the operating authorization or by the competent authority in each case.', 'Spain', 'climate', 'in_force', '2007-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_57', ARRAY['sdg13', 'regulations', 'mandatory', 'disclosure', 'spain', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('08246b60-0a70-5ee7-922a-73371fcd227c', 'Spain Organic Law , of March 22, for the', 'Organic Law 3/2007, of March 22, for the effective equality of women and men', 'To favor the incorporation of women into the labor market, an objective of this law is established to improve access and permanence in employment for women, enhancing their educational level and their adaptability to the requirements of the labor market through their possible consideration as a group priority population of active employment policies. Likewise, the law includes a series of specific social and labor measures, which are regulated in the different additional provisions of the Law.', 'To favor the incorporation of women into the labor market, an objective of this law is established to improve access and permanence in employment for women, enhancing their educational level and their adaptability to the requirements of the labor market through their possible consideration as a group priority population of active employment policies. Likewise, the law includes a series of specific social and labor measures, which are regulated in the different additional provisions of the Law.', 'To favor the incorporation of women into the labor market, an objective of this law is established to improve access and permanence in employment for women, enhancing their educational level and their adaptability to the requirements of the labor market through their possible consideration as a group priority population of active employment policies. Likewise, the law includes a series of specific social and labor measures, which are regulated in the different additional provisions of the Law.', 'Spain', 'social', 'in_force', '2007-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_9', ARRAY['sdg4', 'sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'sdg5', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('128b641d-effd-5327-822e-6d3365a7b96f', 'Spain Code of Ethics for Companies', 'Code of Ethics for Companies, 2006', 'Even though this Code has been created with the intention of being applicable in general to all companies, it should also be understood within a general and basic framework subject to adaptation to the specific circumstances of each business; thereby ensuring that it contemplates application of the principles of ethics and sustainable development in accordance with the specific activity of the company involved.', 'Even though this Code has been created with the intention of being applicable in general to all companies, it should also be understood within a general and basic framework subject to adaptation to the specific circumstances of each business; thereby ensuring that it contemplates application of the principles of ethics and sustainable development in accordance with the specific activity of the company involved.', 'Even though this Code has been created with the intention of being applicable in general to all companies, it should also be understood within a general and basic framework subject to adaptation to the specific circumstances of each business; thereby ensuring that it contemplates application of the principles of ethics and sustainable development in accordance with the specific activity of the company involved.', 'Spain', 'climate', 'in_force', '2006-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_19', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c70e2015-a92b-58ce-9c18-3001a1110dcd', 'Spain Unified Code on Good Corporate Governance (Draft)', 'Unified Code on Good Corporate Governance (Draft), 2006', 'Good governance recommendations for companies whose shares are traded on the Spanish Stock Exchange, although work may later go into adapting the Code to the issuers of fixed-income securities (in particular, savings banks).', 'Good governance recommendations for companies whose shares are traded on the Spanish Stock Exchange, although work may later go into adapting the Code to the issuers of fixed-income securities (in particular, savings banks).', 'Good governance recommendations for companies whose shares are traded on the Spanish Stock Exchange, although work may later go into adapting the Code to the issuers of fixed-income securities (in particular, savings banks).', 'Spain', 'governance', 'in_force', '2006-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_23', ARRAY['guidance_frameworks', 'mandatory', 'sdg16', 'disclosure', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('16a5dccc-0ebb-53d5-98d2-ba2b9fdfbaca', 'Spain Report of the Special Working Group on the', 'Report of the Special Working Group on the Good Governance of Listed Companies', 'This document is a report of the special working group on the Good Governance of listed companies.', 'This document is a report of the special working group on the Good Governance of listed companies.', 'This document is a report of the special working group on the Good Governance of listed companies.', 'Spain', 'climate', 'in_force', '2006-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_27', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6daecb58-8f81-5ead-95b5-91724b3a7560', 'Spain Order FOM/, of September 19, which regulates the', 'Order FOM/2924/2006, of September 19, which regulates the minimum content of the annual report for the transport of dangerous goods by road, rail or waterway', 'Order FOM/2924/2006 of Sept. 19, 2006, outlines the content and format of the annual reports that must be submitted to the competent authorities by safety advisors appointed to oversee the transport of dangerous goods by road, rail or inland waterways. Under Royal Decree 1566/1999, which transposed EU Directive 96/35/EC, companies that transport or load or unload dangerous goods by road, rail or inland waterway must appoint one or more safety advisors who have met specific qualifications. A company may be exempt from having to appoint a safety advisor if it transports limited quantities of dangerous goods or if it is only occasionally involved in the transport of low-risk dangerous goods within the national territory.', 'Order FOM/2924/2006 of Sept. 19, 2006, outlines the content and format of the annual reports that must be submitted to the competent authorities by safety advisors appointed to oversee the transport of dangerous goods by road, rail or inland waterways. Under Royal Decree 1566/1999, which transposed EU Directive 96/35/EC, companies that transport or load or unload dangerous goods by road, rail or inland waterway must appoint one or more safety advisors who have met specific qualifications. A company may be exempt from having to appoint a safety advisor if it transports limited quantities of dangerous goods or if it is only occasionally involved in the transport of low-risk dangerous goods within the national territory.', 'Order FOM/2924/2006 of Sept. 19, 2006, outlines the content and format of the annual reports that must be submitted to the competent authorities by safety advisors appointed to oversee the transport of dangerous goods by road, rail or inland waterways. Under Royal Decree 1566/1999, which transposed EU Directive 96/35/EC, companies that transport or load or unload dangerous goods by road, rail or inland waterway must appoint one or more safety advisors who have met specific qualifications. A company may be exempt from having to appoint a safety advisor if it transports limited quantities of dangerous goods or if it is only occasionally involved in the transport of low-risk dangerous goods within the national territory.', 'Spain', 'climate', 'in_force', '2006-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_58', ARRAY['sdg11', 'mandatory', 'sdg6', 'mandatory_regulations', 'disclosure', 'spain', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b0cba543-3aff-5a3e-9355-9e8b0c2077d9', 'Spain Resolution of February 8, 2006, of the Institute', 'Resolution of February 8, 2006, of the Institute of Accounting and Audit of Accounts, by which They approve standards for the registration, valuation and information of greenhouse gas emission rights.', 'This Royal Decree 1643/1990, of December 20, approves the General Accounting Plan, in its fifth final provision establishes that the Institute of Accounting and Auditing of Accounts, through a Resolution, may issue mandatory rules that develop the valuation standards of the General Accounting Plan.', 'This Royal Decree 1643/1990, of December 20, approves the General Accounting Plan, in its fifth final provision establishes that the Institute of Accounting and Auditing of Accounts, through a Resolution, may issue mandatory rules that develop the valuation standards of the General Accounting Plan.', 'This Royal Decree 1643/1990, of December 20, approves the General Accounting Plan, in its fifth final provision establishes that the Institute of Accounting and Auditing of Accounts, through a Resolution, may issue mandatory rules that develop the valuation standards of the General Accounting Plan.', 'Spain', 'climate', 'in_force', '2006-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_7', ARRAY['sdg13', 'voluntary_frameworks', 'other sustainability policy', 'spain', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('76ee635d-1ee8-5b54-bbd3-f5f25ba9590a', 'Spain IC-A: Principles of Good Corporate Governance for Unlisted', 'IC-A: Principles of Good Corporate Governance for Unlisted Companies, 2005', 'The purpose of this document is to offer Spanish companies that are considering the creation of a Board of Directors, and the Directors and Boards of Directors of Unlisted companies a set of principles which relate to international best practices for Good Corporate Governance duly adapted to the characteristics of Unlisted companies. When drafting this work, we sought practical, gradually adapted and widely accepted proposals that correlate with the "comply or explain” principle.', 'The purpose of this document is to offer Spanish companies that are considering the creation of a Board of Directors, and the Directors and Boards of Directors of Unlisted companies a set of principles which relate to international best practices for Good Corporate Governance duly adapted to the characteristics of Unlisted companies. When drafting this work, we sought practical, gradually adapted and widely accepted proposals that correlate with the "comply or explain” principle.', 'The purpose of this document is to offer Spanish companies that are considering the creation of a Board of Directors, and the Directors and Boards of Directors of Unlisted companies a set of principles which relate to international best practices for Good Corporate Governance duly adapted to the characteristics of Unlisted companies. When drafting this work, we sought practical, gradually adapted and widely accepted proposals that correlate with the "comply or explain” principle.', 'Spain', 'governance', 'in_force', '2005-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_25', ARRAY['guidance_frameworks', 'other sustainability policy', 'sdg16', 'spain', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ec50b114-81e0-55d0-a658-54bc2e25132f', 'Spain Law , of March 9, which regulates the', 'Law 1/2005, of March 9, which regulates the trading system for greenhouse gas emission rights', 'Through Law 1/2005, Spain has implemented the EU Emissions Trading System (ETS), the most important European measure pursuing the reduction of greenhouse gas.  We are currently in the third phase (2013–2020), which is consistent with the second commitment period of the Kyoto Protocol. According to Law 1/2005, which also incorporates the provisions set by the Commission Regulation 601/2012 on Monitoring and Reporting, owners of facilities have to implement and maintain a monitoring system of greenhouse gas in compliance with the conditions of their emissions authorization, and to submit an annual report before the competent authorities before February 28th each year.', 'Through Law 1/2005, Spain has implemented the EU Emissions Trading System (ETS), the most important European measure pursuing the reduction of greenhouse gas.  We are currently in the third phase (2013–2020), which is consistent with the second commitment period of the Kyoto Protocol. According to Law 1/2005, which also incorporates the provisions set by the Commission Regulation 601/2012 on Monitoring and Reporting, owners of facilities have to implement and maintain a monitoring system of greenhouse gas in compliance with the conditions of their emissions authorization, and to submit an annual report before the competent authorities before February 28th each year.', 'Through Law 1/2005, Spain has implemented the EU Emissions Trading System (ETS), the most important European measure pursuing the reduction of greenhouse gas.  We are currently in the third phase (2013–2020), which is consistent with the second commitment period of the Kyoto Protocol. According to Law 1/2005, which also incorporates the provisions set by the Commission Regulation 601/2012 on Monitoring and Reporting, owners of facilities have to implement and maintain a monitoring system of greenhouse gas in compliance with the conditions of their emissions authorization, and to submit an annual report before the competent authorities before February 28th each year.', 'Spain', 'climate', 'in_force', '2005-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_54', ARRAY['sdg13', 'regulations', 'mandatory', 'disclosure', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f0ead580-0e49-5ffa-8526-1c7c8e80555f', 'Spain Decalogue of the Manager', 'Decalogue of the Manager, 2004', 'The manager assumes an important social responsibility. In your activity, you must respond to the trust that ownership of the company has given you by achieving the agreed objectives, while respecting the legal system, the commitments made and property rights, but being aware that, in order to It is not worth everything nor is it possible to do it without the sincere complicity of all its collaborators.', 'The manager assumes an important social responsibility. In your activity, you must respond to the trust that ownership of the company has given you by achieving the agreed objectives, while respecting the legal system, the commitments made and property rights, but being aware that, in order to It is not worth everything nor is it possible to do it without the sincere complicity of all its collaborators.', 'The manager assumes an important social responsibility. In your activity, you must respond to the trust that ownership of the company has given you by achieving the agreed objectives, while respecting the legal system, the commitments made and property rights, but being aware that, in order to It is not worth everything nor is it possible to do it without the sincere complicity of all its collaborators.', 'Spain', 'climate', 'in_force', '2004-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_22', ARRAY['spain', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8d86c4b4-0be6-5433-a3da-0dc0e3bbf160', 'Spain IC-A: Principles of Good Corporate Governance', 'IC-A: Principles of Good Corporate Governance, 2004', 'The purpose of this document is to provide Spanish Company Boards and Directors with a set of principles which relate to international best practices for good corporate governance. When drafting this work, we sought practical, widely accepted proposals that correlate with the "comply or explain” principle.', 'The purpose of this document is to provide Spanish Company Boards and Directors with a set of principles which relate to international best practices for good corporate governance. When drafting this work, we sought practical, widely accepted proposals that correlate with the "comply or explain” principle.', 'The purpose of this document is to provide Spanish Company Boards and Directors with a set of principles which relate to international best practices for good corporate governance. When drafting this work, we sought practical, widely accepted proposals that correlate with the "comply or explain” principle.', 'Spain', 'governance', 'in_force', '2004-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_24', ARRAY['guidance_frameworks', 'sdg16', 'disclosure', 'spain', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bf98faa8-39e6-5e58-bd3c-4f5b69ab43e7', 'Spain Report by the Special Commission to Foster Transparency', 'Report by the Special Commission to Foster Transparency and Security in the Markets and in Listed Companies', 'As a result of the creation of the special commission, it drafted this Report, which begins with this preamble, continues with a reflection on the criteria of transparency and security in the markets and makes a number of recommendations about the relationship between listed companies and the aforementioned professional services firms and about improved corporate governance, in line with the mandate it received. The Commission is in agreement on the overall document presented as a Report, even if it does not reflect the individual opinion of each of its members about each of the matters which are discussed.', 'As a result of the creation of the special commission, it drafted this Report, which begins with this preamble, continues with a reflection on the criteria of transparency and security in the markets and makes a number of recommendations about the relationship between listed companies and the aforementioned professional services firms and about improved corporate governance, in line with the mandate it received. The Commission is in agreement on the overall document presented as a Report, even if it does not reflect the individual opinion of each of its members about each of the matters which are discussed.', 'As a result of the creation of the special commission, it drafted this Report, which begins with this preamble, continues with a reflection on the criteria of transparency and security in the markets and makes a number of recommendations about the relationship between listed companies and the aforementioned professional services firms and about improved corporate governance, in line with the mandate it received. The Commission is in agreement on the overall document presented as a Report, even if it does not reflect the individual opinion of each of its members about each of the matters which are discussed.', 'Spain', 'climate', 'in_force', '2003-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_26', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b24cbd57-486a-549a-8e13-473c7a586c44', 'Spain Royal Legislative Decree , of November 29, approving', 'Royal Legislative Decree 1/2002, of November 29, approving the revised text of the Law Regulating Pension Plans and Funds.', 'This Law 24/2001, of December 27, on fiscal, administrative and social order measures, in its article 32, section eighteen, authorizes the Government so that, within a period of twelve months from the entry into force of the the same, prepare and approve a revised text of the Law on the Regulation of Pension Plans and Funds, in which Law 8/1987, of June 8, on the Regulation of Plans and Pension Funds, is integrated, duly regularized, clarified and systematized. Pension Funds, and other provisions related to pension plans and funds.', 'This Law 24/2001, of December 27, on fiscal, administrative and social order measures, in its article 32, section eighteen, authorizes the Government so that, within a period of twelve months from the entry into force of the the same, prepare and approve a revised text of the Law on the Regulation of Pension Plans and Funds, in which Law 8/1987, of June 8, on the Regulation of Plans and Pension Funds, is integrated, duly regularized, clarified and systematized. Pension Funds, and other provisions related to pension plans and funds.', 'This Law 24/2001, of December 27, on fiscal, administrative and social order measures, in its article 32, section eighteen, authorizes the Government so that, within a period of twelve months from the entry into force of the the same, prepare and approve a revised text of the Law on the Regulation of Pension Plans and Funds, in which Law 8/1987, of June 8, on the Regulation of Plans and Pension Funds, is integrated, duly regularized, clarified and systematized. Pension Funds, and other provisions related to pension plans and funds.', 'Spain', 'governance', 'in_force', '2002-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_29', ARRAY['spain', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('91689a0a-1aab-57e1-a79f-bd742277625c', 'Spain Orders Tas/, of November 19, which establishes new', 'Orders Tas/2926/2002, of November 19, which establishes new models for the notification of work accidents and enables their transmission by electronic procedure.', 'The Order of December 16, 1987 established new models for the notification of work accidents and regulated the procedure for its completion and processing.', 'The Order of December 16, 1987 established new models for the notification of work accidents and regulated the procedure for its completion and processing.', 'The Order of December 16, 1987 established new models for the notification of work accidents and regulated the procedure for its completion and processing.', 'Spain', 'governance', 'in_force', '2002-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_32', ARRAY['spain', 'guidance_frameworks', 'mandatory', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f9738c85-3ee3-5a8f-bc8a-76954a2bcac4', 'Spain RESOLUTION of March 25, 2002, of the Institute', 'RESOLUTION of March 25, 2002, of the Institute of Accounting and Auditing of Accounts, which approves standards for the recognition, valuation and information of environmental aspects in the annual accounts', 'This regulation develops the aspects related to environmental accounting, incorporated in Royal Decree 437/1998. It has the objective to help companies to recognize, value and collect information on environmental issues in their annual accounts. It includes information about environmental responsibilities, company''s environmental costs; environmental assets; environmental provisions and contingencies; and long-term obligations for environmental repair. It also includes the information that must be reported in the annual accounts and the location where environmental information could be reported.', 'This regulation develops the aspects related to environmental accounting, incorporated in Royal Decree 437/1998. It has the objective to help companies to recognize, value and collect information on environmental issues in their annual accounts. It includes information about environmental responsibilities, company''s environmental costs; environmental assets; environmental provisions and contingencies; and long-term obligations for environmental repair. It also includes the information that must be reported in the annual accounts and the location where environmental information could be reported.', 'This regulation develops the aspects related to environmental accounting, incorporated in Royal Decree 437/1998. It has the objective to help companies to recognize, value and collect information on environmental issues in their annual accounts. It includes information about environmental responsibilities, company''s environmental costs; environmental assets; environmental provisions and contingencies; and long-term obligations for environmental repair. It also includes the information that must be reported in the annual accounts and the location where environmental information could be reported.', 'Spain', 'climate', 'in_force', '2002-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_53', ARRAY['spain', 'voluntary_frameworks', 'voluntary', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('db5866f8-8417-5357-9a43-50d0bd79861d', 'Spain Resolution of March 25, 2002, of the Institute', 'Resolution of March 25, 2002, of the Institute of Accounting and Audit of Accounts, approving standards for the recognition, valuation and information of environmental aspects in the annual accounts', 'This Royal Decree 1643/1990, of December 20, approves the General Accounting Plan, in its fifth final provision establishes that the Institute of Accounting and Audit of Accounts, through a Resolution, and may dictate mandatory regulations that develop the valuation standards of the General Accounting Plan.', 'This Royal Decree 1643/1990, of December 20, approves the General Accounting Plan, in its fifth final provision establishes that the Institute of Accounting and Audit of Accounts, through a Resolution, and may dictate mandatory regulations that develop the valuation standards of the General Accounting Plan.', 'This Royal Decree 1643/1990, of December 20, approves the General Accounting Plan, in its fifth final provision establishes that the Institute of Accounting and Audit of Accounts, through a Resolution, and may dictate mandatory regulations that develop the valuation standards of the General Accounting Plan.', 'Spain', 'governance', 'in_force', '2002-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_6', ARRAY['spain', 'voluntary_frameworks', 'voluntary', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c4be14d1-7fdd-5611-94a8-d93f92edbd51', 'Spain Royal Legislative Decree , of November 29', 'Royal Legislative Decree 1/2002, of November 29, by which approves the consolidated text of the Law for the Regulation of Pension Plans and Funds.', 'This Law 24/2001, of December 27, on fiscal, administrative and social order measures, in its article 32, section eighteen, authorizes the Government so that, within a period of twelve months from the entry into force of the same , elaborates and approves the consolidated text of the Law of Regulation of Plans and Funds of Pensions, in which they integrate, duly regularized, clarified and systematized the Law 8/1987, of June 8, of Regulation of Plans and Funds of Pensions, and other provisions that it indicates relative to pension plans and funds.', 'This Law 24/2001, of December 27, on fiscal, administrative and social order measures, in its article 32, section eighteen, authorizes the Government so that, within a period of twelve months from the entry into force of the same , elaborates and approves the consolidated text of the Law of Regulation of Plans and Funds of Pensions, in which they integrate, duly regularized, clarified and systematized the Law 8/1987, of June 8, of Regulation of Plans and Funds of Pensions, and other provisions that it indicates relative to pension plans and funds.', 'This Law 24/2001, of December 27, on fiscal, administrative and social order measures, in its article 32, section eighteen, authorizes the Government so that, within a period of twelve months from the entry into force of the same , elaborates and approves the consolidated text of the Law of Regulation of Plans and Funds of Pensions, in which they integrate, duly regularized, clarified and systematized the Law 8/1987, of June 8, of Regulation of Plans and Funds of Pensions, and other provisions that it indicates relative to pension plans and funds.', 'Spain', 'governance', 'in_force', '2002-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_8', ARRAY['spain', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9da68d79-a1df-5c70-be49-6a2f5b632b59', 'Spain Royal Legislative Decree , of July 20, approving', 'Royal Legislative Decree 1/2001, of July 20, approving the consolidated text of the Water Law', 'Under Royal Decree 1/2001, a facility that holds a valid wastewater license must submit an annual report to the competent Water Basin Authority or local administration of the autonomous community where it is operating. The report must be submitted in the format and by the deadline specified by each environmental authority. Generally, the wastewater discharge report must include the following information: characteristics of the activity generating effluents; exact location of the discharge points; qualitative, quantitative and temporary characteristics of the discharge; description of the treatment processes.', 'Under Royal Decree 1/2001, a facility that holds a valid wastewater license must submit an annual report to the competent Water Basin Authority or local administration of the autonomous community where it is operating. The report must be submitted in the format and by the deadline specified by each environmental authority. Generally, the wastewater discharge report must include the following information: characteristics of the activity generating effluents; exact location of the discharge points; qualitative, quantitative and temporary characteristics of the discharge; description of the treatment processes.', 'Under Royal Decree 1/2001, a facility that holds a valid wastewater license must submit an annual report to the competent Water Basin Authority or local administration of the autonomous community where it is operating. The report must be submitted in the format and by the deadline specified by each environmental authority. Generally, the wastewater discharge report must include the following information: characteristics of the activity generating effluents; exact location of the discharge points; qualitative, quantitative and temporary characteristics of the discharge; description of the treatment processes.', 'Spain', 'climate', 'in_force', '2001-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_61', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'sdg6', 'sdg12', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('493d7f9f-8b25-5a68-9c92-a81eb134c9e2', 'Spain Governance of Listed Companies', 'The Governance of Listed Companies, 1998', 'This Commission believes that the general supervisory function is the most genuine function of the Board of Directors in listed companies, and it identifies three basic responsibilities within that function: to guide the company''s policy, control its management echelons and liaise with the shareholders.', 'This Commission believes that the general supervisory function is the most genuine function of the Board of Directors in listed companies, and it identifies three basic responsibilities within that function: to guide the company''s policy, control its management echelons and liaise with the shareholders.', 'This Commission believes that the general supervisory function is the most genuine function of the Board of Directors in listed companies, and it identifies three basic responsibilities within that function: to guide the company''s policy, control its management echelons and liaise with the shareholders.', 'Spain', 'governance', 'in_force', '1998-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_20', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ce1f1556-452c-54d6-87ee-938177472d10', 'Spain Royal Decree , of March 20, which approves', 'Royal Decree 437/1998, of March 20, which approves the rules for adapting the General Accounting Plan to companies in the electricity sector', 'The electricity utilities’ AGAP (RD 437/98) requires environmental disclosure in the notes to the financial statements. Note 4 requires the disclosure of accounting policy about environmental assets, expenses and liabilities. Note 18 involves the disclosure of expenses on energy saving and efficiency programs. Finally, Note 19 requires a description of the nature and the amount of environmental investments, expenses, provisions and contingent liabilities. The approach adopted by the Spanish standard is that environmental issues can be successfully integrated in the conventional accounting model.', 'The electricity utilities’ AGAP (RD 437/98) requires environmental disclosure in the notes to the financial statements. Note 4 requires the disclosure of accounting policy about environmental assets, expenses and liabilities. Note 18 involves the disclosure of expenses on energy saving and efficiency programs. Finally, Note 19 requires a description of the nature and the amount of environmental investments, expenses, provisions and contingent liabilities. The approach adopted by the Spanish standard is that environmental issues can be successfully integrated in the conventional accounting model.', 'The electricity utilities’ AGAP (RD 437/98) requires environmental disclosure in the notes to the financial statements. Note 4 requires the disclosure of accounting policy about environmental assets, expenses and liabilities. Note 18 involves the disclosure of expenses on energy saving and efficiency programs. Finally, Note 19 requires a description of the nature and the amount of environmental investments, expenses, provisions and contingent liabilities. The approach adopted by the Spanish standard is that environmental issues can be successfully integrated in the conventional accounting model.', 'Spain', 'climate', 'in_force', '1998-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_52', ARRAY['regulations', 'sdg7', 'mandatory', 'spain', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f0d93a58-1697-5efa-bb66-4de1cfab7229', 'Sri Lanka CSE Sustainability Reporting Guide (Version 3)', 'CSE Sustainability Reporting Guide (Version 3)', 'The guide seeks to support corporates in preparing their sustainability reports.', 'The guide seeks to support corporates in preparing their sustainability reports.', 'The guide seeks to support corporates in preparing their sustainability reports.', 'Sri Lanka', 'climate', 'in_force', '2023-01-01'::date, 'Sri Lanka', 'https://www.carrotsandsticks.org/policies/169_11', ARRAY['sri lanka', 'sdg13', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4348a0e6-e4bd-53b8-9b6c-eb968a7e2640', 'Sri Lanka Green Finance Taxonomy', 'Sri Lanka Green Finance Taxonomy', 'Launched in 2022, Sri Lanka''s Green Finance Taxonomy categorizes green activities for financiers and businesses. Aligning with global standards and local priorities, it defines what''s "green" for climate mitigation, adaptation, and other environmental goals. Though voluntary, it guides responsible investments, mobilizes capital towards green projects, and positions Sri Lanka as a sustainable finance leader.', 'Launched in 2022, Sri Lanka''s Green Finance Taxonomy categorizes green activities for financiers and businesses. Aligning with global standards and local priorities, it defines what''s "green" for climate mitigation, adaptation, and other environmental goals. Though voluntary, it guides responsible investments, mobilizes capital towards green projects, and positions Sri Lanka as a sustainable finance leader.', 'Launched in 2022, Sri Lanka''s Green Finance Taxonomy categorizes green activities for financiers and businesses. Aligning with global standards and local priorities, it defines what''s "green" for climate mitigation, adaptation, and other environmental goals. Though voluntary, it guides responsible investments, mobilizes capital towards green projects, and positions Sri Lanka as a sustainable finance leader.', 'Sri Lanka', 'climate', 'in_force', '2022-01-01'::date, 'Sri Lanka', 'https://www.carrotsandsticks.org/policies/169_10', ARRAY['sri lanka', 'sdg13', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d0a5e3c2-adea-5248-835b-77607c09ab6c', 'Sri Lanka Communicating Sustainability: Six Recommendations for Listed Companies', 'Communicating Sustainability: Six Recommendations for Listed Companies (version 2)', 'This guide will help companies listed in the Colombo Stock Exchange address topics related to environmental, social and governance (ESG) issues in their communications, as these aspects are among the factors influencing investment decisions by institutional and retail investors. The guide consolidates the current practices of investors and issuers and aims to provide guidance. It consists of useful recommendations related to sustainability reporting for companies.', 'This guide will help companies listed in the Colombo Stock Exchange address topics related to environmental, social and governance (ESG) issues in their communications, as these aspects are among the factors influencing investment decisions by institutional and retail investors. The guide consolidates the current practices of investors and issuers and aims to provide guidance. It consists of useful recommendations related to sustainability reporting for companies.', 'This guide will help companies listed in the Colombo Stock Exchange address topics related to environmental, social and governance (ESG) issues in their communications, as these aspects are among the factors influencing investment decisions by institutional and retail investors. The guide consolidates the current practices of investors and issuers and aims to provide guidance. It consists of useful recommendations related to sustainability reporting for companies.', 'Sri Lanka', 'climate', 'in_force', '2019-01-01'::date, 'Sri Lanka', 'https://www.carrotsandsticks.org/policies/169_2', ARRAY['sri lanka', 'guidance_frameworks', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2f29d08c-8417-57ac-ba5b-6ce32bd41948', 'Sri Lanka Environmental Norms', 'Environmental Norms', 'The Board of Investment of Sri Lanka issued Environmental Norms of Sri Lanka to assist companies in complying with the various environmental standards that exist in Sri Lanka. The guidance lists the environmental standards that exist for various emissions and effluents that are applicable to companies working in various sectors of the Sri Lankan economy. In addition, the Environmental Norms of Sri Lanka sets out those operations or developments that are subject to environmental impact assessments. Compiling all this information in one place allows companies, especially that are based outside of Sri Lanka, to easily understand the how, what and where of environmental reporting.', 'The Board of Investment of Sri Lanka issued Environmental Norms of Sri Lanka to assist companies in complying with the various environmental standards that exist in Sri Lanka. The guidance lists the environmental standards that exist for various emissions and effluents that are applicable to companies working in various sectors of the Sri Lankan economy. In addition, the Environmental Norms of Sri Lanka sets out those operations or developments that are subject to environmental impact assessments. Compiling all this information in one place allows companies, especially that are based outside of Sri Lanka, to easily understand the how, what and where of environmental reporting.', 'The Board of Investment of Sri Lanka issued Environmental Norms of Sri Lanka to assist companies in complying with the various environmental standards that exist in Sri Lanka. The guidance lists the environmental standards that exist for various emissions and effluents that are applicable to companies working in various sectors of the Sri Lankan economy. In addition, the Environmental Norms of Sri Lanka sets out those operations or developments that are subject to environmental impact assessments. Compiling all this information in one place allows companies, especially that are based outside of Sri Lanka, to easily understand the how, what and where of environmental reporting.', 'Sri Lanka', 'climate', 'in_force', '2019-01-01'::date, 'Sri Lanka', 'https://www.carrotsandsticks.org/policies/169_6', ARRAY['sri lanka', 'sdg13', 'other sustainability policy', 'regulations', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('39cb97c3-b80a-57d5-954b-3ce67526d493', 'Labour Code of Sri Lanka (Chapter 4)', 'Labour Code of Sri Lanka (Chapter 4)', 'Article 61 of Chapter 4 of the Labour Code of Sri Lanka requires all factory occupiers, managers or superintendents to report to the District Factory inspecting Engineer in cases of an accident that leads to loss of life of a person employed in the factory, disables them for more than three days, or makes them unconscious due to heat, exhaustion, electric shock or inhalation of fumes/gases. The report is to detail all particulars of the accident and should be delivered to the District Factory Inspecting Engineer as soon as possible. More broadly, Chapter 4 of the Labour Code of Sri Lanka sets out the requirements and expectations of employee health, safety and hygiene that must be met by all factories in Sri Lanka.', 'Article 61 of Chapter 4 of the Labour Code of Sri Lanka requires all factory occupiers, managers or superintendents to report to the District Factory inspecting Engineer in cases of an accident that leads to loss of life of a person employed in the factory, disables them for more than three days, or makes them unconscious due to heat, exhaustion, electric shock or inhalation of fumes/gases. The report is to detail all particulars of the accident and should be delivered to the District Factory Inspecting Engineer as soon as possible. More broadly, Chapter 4 of the Labour Code of Sri Lanka sets out the requirements and expectations of employee health, safety and hygiene that must be met by all factories in Sri Lanka.', 'Article 61 of Chapter 4 of the Labour Code of Sri Lanka requires all factory occupiers, managers or superintendents to report to the District Factory inspecting Engineer in cases of an accident that leads to loss of life of a person employed in the factory, disables them for more than three days, or makes them unconscious due to heat, exhaustion, electric shock or inhalation of fumes/gases. The report is to detail all particulars of the accident and should be delivered to the District Factory Inspecting Engineer as soon as possible. More broadly, Chapter 4 of the Labour Code of Sri Lanka sets out the requirements and expectations of employee health, safety and hygiene that must be met by all factories in Sri Lanka.', 'Sri Lanka', 'climate', 'in_force', '2019-01-01'::date, 'Sri Lanka', 'https://www.carrotsandsticks.org/policies/169_7', ARRAY['sri lanka', 'sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('824cfbeb-f780-5693-98f9-c0fd7b930271', 'Sri Lanka Listing Rules of Colombo Stock Exchange', 'Listing Rules of Colombo Stock Exchange', 'Article 7.5 of the Listing Rules of Colombo Stock Exchange requires all listed companies to produce an annual report and for it to be circulated to shareholders and the Colombo Stock Exchange no more than five months after the close of the financial year. The financial statements of the annual report shall be completed in accordance with the Sri Lanka Accounting Standards and shall be audited in accordance with the Sri Lanka Auditing Standards. Article 7.6 of the Listing Rules sets out the required content of the annual report and accounts of listed companies, which includes various results and particulars of the company, information about material foreseeable risk factors and employee/industrial relations, and details of corporate governance practices. The corporate governance disclosures shall include how the listed company complies with the Code of Best Practice on Corporate Governance  as well as key details around governance structure and role, audit, and remuneration.', 'Article 7.5 of the Listing Rules of Colombo Stock Exchange requires all listed companies to produce an annual report and for it to be circulated to shareholders and the Colombo Stock Exchange no more than five months after the close of the financial year. The financial statements of the annual report shall be completed in accordance with the Sri Lanka Accounting Standards and shall be audited in accordance with the Sri Lanka Auditing Standards. Article 7.6 of the Listing Rules sets out the required content of the annual report and accounts of listed companies, which includes various results and particulars of the company, information about material foreseeable risk factors and employee/industrial relations, and details of corporate governance practices. The corporate governance disclosures shall include how the listed company complies with the Code of Best Practice on Corporate Governance  as well as key details around governance structure and role, audit, and remuneration.', 'Article 7.5 of the Listing Rules of Colombo Stock Exchange requires all listed companies to produce an annual report and for it to be circulated to shareholders and the Colombo Stock Exchange no more than five months after the close of the financial year. The financial statements of the annual report shall be completed in accordance with the Sri Lanka Accounting Standards and shall be audited in accordance with the Sri Lanka Auditing Standards. Article 7.6 of the Listing Rules sets out the required content of the annual report and accounts of listed companies, which includes various results and particulars of the company, information about material foreseeable risk factors and employee/industrial relations, and details of corporate governance practices. The corporate governance disclosures shall include how the listed company complies with the Code of Best Practice on Corporate Governance  as well as key details around governance structure and role, audit, and remuneration.', 'Sri Lanka', 'climate', 'in_force', '2019-01-01'::date, 'Sri Lanka', 'https://www.carrotsandsticks.org/policies/169_8', ARRAY['sri lanka', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e6f6588e-cee6-59b5-8cfc-743cf4a23593', 'Sri Lanka Code of best Practice on Corporate Governance', 'Code of best Practice on Corporate Governance 2017', 'This Code of 2017 builds on the previous Codes to strengthen best practice in governance in the context of global developments relevant to Sri Lanka, emerging contemporary matters of governance and challenges with greater importance to the Sri Lankan capital market.', 'This Code of 2017 builds on the previous Codes to strengthen best practice in governance in the context of global developments relevant to Sri Lanka, emerging contemporary matters of governance and challenges with greater importance to the Sri Lankan capital market.', 'This Code of 2017 builds on the previous Codes to strengthen best practice in governance in the context of global developments relevant to Sri Lanka, emerging contemporary matters of governance and challenges with greater importance to the Sri Lankan capital market.', 'Sri Lanka', 'climate', 'in_force', '2017-01-01'::date, 'Sri Lanka', 'https://www.carrotsandsticks.org/policies/169_1', ARRAY['sri lanka', 'other sustainability policy', 'regulations', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0468707a-a177-5ef1-ae72-92bd183016b3', 'Sri Lanka Marine Environmental Protection Regulations', 'Marine Environmental Protection Regulations No 01', 'This document outlines regulations made by the Minister of Environment and Renewable Energy under Section 51 read with Section 27 and 28 of the Marine Pollution Prevention Act, No. 35 of 2008.', 'This document outlines regulations made by the Minister of Environment and Renewable Energy under Section 51 read with Section 27 and 28 of the Marine Pollution Prevention Act, No. 35 of 2008.', 'This document outlines regulations made by the Minister of Environment and Renewable Energy under Section 51 read with Section 27 and 28 of the Marine Pollution Prevention Act, No. 35 of 2008.', 'Sri Lanka', 'climate', 'in_force', '2013-01-01'::date, 'Sri Lanka', 'https://www.carrotsandsticks.org/policies/169_4', ARRAY['sri lanka', 'sdg14', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f14417aa-6dca-5713-90ed-ac29fff24166', 'Sri Lanka Offshore Exploration and Explotation of Natural Resources', 'Offshore Exploration and Explotation of Natural Resources including Petroleum Regulation No 1', 'This document outlines a regulation made by the Minister under Section 51 read with section 40 of the Marine Pollution Prevention Act, No. 35 of 2008 and in accordance with the direction of the Cabinet of Ministers.', 'This document outlines a regulation made by the Minister under Section 51 read with section 40 of the Marine Pollution Prevention Act, No. 35 of 2008 and in accordance with the direction of the Cabinet of Ministers.', 'This document outlines a regulation made by the Minister under Section 51 read with section 40 of the Marine Pollution Prevention Act, No. 35 of 2008 and in accordance with the direction of the Cabinet of Ministers.', 'Sri Lanka', 'climate', 'in_force', '2011-01-01'::date, 'Sri Lanka', 'https://www.carrotsandsticks.org/policies/169_5', ARRAY['sri lanka', 'sdg14', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('36562545-b357-59ac-8ee0-c04faa614e17', 'Sri Lanka Marine Pollution Prevention Act', 'Marine Pollution Prevention Act No. 35/2008', 'Marine Pollution Prevention Act, passed in 2008, sets out the rules and expectations of all vessels that enter the waters of Sri Lanka as well as setting up and formulating the remit of the Marine Environment Protection Authority. As part of these regulations, vessels must keep an oil record book, which is to log all oil, harmful substances and other pollutants that are loaded, transferred, discharged, disposed or leaked. In cases where oil or other pollutant is discharged, escapes or is dumped in Sri Lankan waters, the operator is report to the authorities with full details of the incident. Moreover, it is required that Contingency Plans be approved by the Marine Environment Protection Authority within three months of coming into operation.', 'Marine Pollution Prevention Act, passed in 2008, sets out the rules and expectations of all vessels that enter the waters of Sri Lanka as well as setting up and formulating the remit of the Marine Environment Protection Authority. As part of these regulations, vessels must keep an oil record book, which is to log all oil, harmful substances and other pollutants that are loaded, transferred, discharged, disposed or leaked. In cases where oil or other pollutant is discharged, escapes or is dumped in Sri Lankan waters, the operator is report to the authorities with full details of the incident. Moreover, it is required that Contingency Plans be approved by the Marine Environment Protection Authority within three months of coming into operation.', 'Marine Pollution Prevention Act, passed in 2008, sets out the rules and expectations of all vessels that enter the waters of Sri Lanka as well as setting up and formulating the remit of the Marine Environment Protection Authority. As part of these regulations, vessels must keep an oil record book, which is to log all oil, harmful substances and other pollutants that are loaded, transferred, discharged, disposed or leaked. In cases where oil or other pollutant is discharged, escapes or is dumped in Sri Lankan waters, the operator is report to the authorities with full details of the incident. Moreover, it is required that Contingency Plans be approved by the Marine Environment Protection Authority within three months of coming into operation.', 'Sri Lanka', 'climate', 'in_force', '2008-01-01'::date, 'Sri Lanka', 'https://www.carrotsandsticks.org/policies/169_9', ARRAY['sri lanka', 'sdg14', 'other sustainability policy', 'regulations', 'mandatory', 'sdg6']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9e6975eb-a5e7-5b7a-88cb-024493a61e5b', 'Suriname Environmental Assessment Guidelines Volume 1: Generic. Second Edition', 'Environmental Assessment Guidelines Volume 1: Generic. Second Edition: August 2009', 'This document is the second edition of the Environmental Assessment Guidelines Volume I: Generic. The new edition includes guidelines for Environmental Management Systems and Environmental Management Plans. Although the legislative framework regarding these Guidelines is not yet in place all stakeholders, both governmental and non-governmental, are strongly urged to use these guidelines as a basis for good environmental management practices.', 'This document is the second edition of the Environmental Assessment Guidelines Volume I: Generic. The new edition includes guidelines for Environmental Management Systems and Environmental Management Plans. Although the legislative framework regarding these Guidelines is not yet in place all stakeholders, both governmental and non-governmental, are strongly urged to use these guidelines as a basis for good environmental management practices.', 'This document is the second edition of the Environmental Assessment Guidelines Volume I: Generic. The new edition includes guidelines for Environmental Management Systems and Environmental Management Plans. Although the legislative framework regarding these Guidelines is not yet in place all stakeholders, both governmental and non-governmental, are strongly urged to use these guidelines as a basis for good environmental management practices.', 'Suriname', 'governance', 'in_force', '2009-01-01'::date, 'Suriname', 'https://www.carrotsandsticks.org/policies/196_2', ARRAY['suriname', 'guidance_frameworks', 'voluntary', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('40270afb-b240-50b9-a490-d99d1154fd0b', 'Home Builders SASB Standards', 'Home Builders SASB Standards, 2018', 'This is the SASB  Sustainability Accounting Standard that is concerned with Home Builders.', 'This is the SASB  Sustainability Accounting Standard that is concerned with Home Builders.', 'This is the SASB  Sustainability Accounting Standard that is concerned with Home Builders.', 'SASB', 'climate', 'in_force', '2018-01-01'::date, 'Sustainability Accounting Standards Board (SASB)', 'https://www.carrotsandsticks.org/policies/323_1', ARRAY['sasb', 'sdg13', 'voluntary', 'sdg16', 'sdg12', 'disclosure', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
